// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0) && newOwner != address(0));
        vm.prank(caller);
        // Attempt to call transferOwnership – it will revert if caller is not owner
        (bool success,) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
        // If the call succeeded, then owner must be newOwner
        if (success) {
            assertTrue(c.owner() == newOwner);
        }
    }
}

