pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        address initialOwner = c.owner();
        vm.prank(caller);
        c.owned();
        address finalOwner = c.owner();
        assertTrue(finalOwner == initialOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address public constant ORIGINAL_OWNER = address(0);

    function setUp() public { 
        c = new C(); 
    }

    function testFuzz_property(address caller) public {
        // Restrict caller to be the owner for valid calls
        vm.assume(caller == c.owner());

        // Record owner before call
        address ownerBefore = c.owner();

        // Call owned() as the owner
        vm.prank(caller);
        c.owned();

        // After owned() completes, owner should remain unchanged
        assertTrue(c.owner() == ownerBefore);
    }
}
